import{_ as s,o as a,c as e,ag as t}from"./chunks/framework.CxkNbRKf.js";const n="/nada-documentation/images/php-info.png",g=JSON.parse('{"title":"PHP settings","description":"","frontmatter":{},"headers":[],"relativePath":"installation-guide/php-settings.md","filePath":"installation-guide/php-settings.md","lastUpdated":1786379412000}'),l={name:"installation-guide/php-settings.md"};function p(h,i,o,r,d,k){return a(),e("div",null,[...i[0]||(i[0]=[t('<h1 id="php-settings" tabindex="-1">PHP settings <a class="header-anchor" href="#php-settings" aria-label="Permalink to &quot;PHP settings&quot;">​</a></h1><h2 id="finding-the-correct-php-ini" tabindex="-1">Finding the correct php.ini <a class="header-anchor" href="#finding-the-correct-php-ini" aria-label="Permalink to &quot;Finding the correct php.ini&quot;">​</a></h2><p>Create a temporary PHP file (for example <code>info.php</code>) in your NADA web folder:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;?</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">php</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> phpinfo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?&gt;</span></span></code></pre></div><p>Open it in the browser and note <strong>Loaded Configuration File</strong>. Edit that <code>php.ini</code>, then <strong>delete <code>info.php</code></strong> from the server.</p><p><img src="'+n+`" alt="PHP info"></p><hr><h2 id="file-upload-limits" tabindex="-1">File upload limits <a class="header-anchor" href="#file-upload-limits" aria-label="Permalink to &quot;File upload limits&quot;">​</a></h2><p>By default PHP often allows only small uploads (for example 2MB). For large data files, raise both of these together:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">upload_max_filesize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 800M</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">post_max_size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 800M</span></span></code></pre></div><p><code>post_max_size</code> must be at least as large as <code>upload_max_filesize</code>.</p><hr><h2 id="time-zone" tabindex="-1">Time zone <a class="header-anchor" href="#time-zone" aria-label="Permalink to &quot;Time zone&quot;">​</a></h2><p>Set your site’s time zone (<a href="https://www.php.net/manual/en/timezones.php" target="_blank" rel="noreferrer">list of time zones</a>):</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">date.timezone</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;America/New_York&quot;</span></span></code></pre></div><hr><h2 id="execution-time-and-memory" tabindex="-1">Execution time and memory <a class="header-anchor" href="#execution-time-and-memory" aria-label="Permalink to &quot;Execution time and memory&quot;">​</a></h2><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">max_execution_time</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 300</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">memory_limit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 128M</span></span></code></pre></div><p>Increase further if large imports or API jobs time out.</p><hr><h2 id="enable-php-extensions" tabindex="-1">Enable PHP extensions <a class="header-anchor" href="#enable-php-extensions" aria-label="Permalink to &quot;Enable PHP extensions&quot;">​</a></h2><p>NADA requires:</p><ul><li>xsl</li><li>xml</li><li>mbstring</li><li><strong>mysqli</strong> — if using MySQL or MariaDB</li><li><strong>sqlsrv</strong> — if using Microsoft SQL Server (<a href="./installation-sqlsrv.html">Install with SQL Server</a>)</li></ul><p>Use the extension that matches your database choice (MySQL/MariaDB <strong>or</strong> SQL Server — not both required).</p><p><strong>Minimum PHP version:</strong> 7.4 · <strong>Recommended:</strong> PHP 8.x</p><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><p><strong>Recommended:</strong> use <a href="https://www.iis.net/downloads/community/2018/05/php-manager-150-for-iis-10" target="_blank" rel="noreferrer">PHP Manager for IIS</a> to register PHP and enable extensions — see <a href="./platform-windows.html#step-1-install-php-and-register-it-with-iis">Installation (Windows) — Install PHP</a>.</p><p>You can also edit <code>php.ini</code> directly. Enable extensions with <code>.dll</code> names (exact names depend on your PHP build):</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">extension</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=php_xsl.dll</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">extension</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=php_mbstring.dll</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">extension</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=php_mysqli.dll</span></span></code></pre></div><p>Restart IIS or recycle the app pool after saving (or use PHP Manager’s refresh). See <a href="./platform-windows.html">Installation (Windows)</a>.</p><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><p>Prefer your distribution’s packages / <code>phpenmod</code>, for example:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> php-xsl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> php-xml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> php-mbstring</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> php-mysql</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or enable modules if already installed:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> phpenmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xsl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mbstring</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysqli</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apache2</span></span></code></pre></div><p>If you edit <code>php.ini</code> directly, module lines typically look like:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">extension</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=xsl</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">extension</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=mbstring</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">extension</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=mysqli</span></span></code></pre></div><p>See <a href="./platform-linux.html">Installation (Linux)</a>.</p><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./">Installation</a></li><li><a href="./debug.html">Debug</a></li></ul>`,39)])])}const m=s(l,[["render",p]]);export{g as __pageData,m as default};
